{"path":"events.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Gatherings — {{BUSINESS_NAME}}</title>
  <meta name='description' content='Group sound events and calendar at {{BUSINESS_NAME}}. Next event, seats, and what to bring.'>
  <style>
    :root{--bg:#0f1720;--card:#0b1320;--accent:#c8b89a;--muted:#9aa5b1;--glass:rgba(255,255,255,0.04)}
    *{box-sizing:border-box;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,#07111a 0%,#0c1620 100%);color:#e6eef6}
    .wrap{max-width:1100px;margin:30px auto;padding:28px}
    header{display:flex;align-items:center;justify-content:space-between;gap:16px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:64px;height:64px;border-radius:12px;background:linear-gradient(135deg,var(--accent),#7f6b4e);display:grid;place-items:center;color:#07202a;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-weight:600}
    nav a.active{color:var(--accent)}
    .hero{position:relative;overflow:hidden;border-radius:14px;margin-top:18px;padding:28px;display:grid;grid-template-columns:1fr 360px;gap:18px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    /* diagonal split */
    .hero::after{content:'';position:absolute;left:50%;top:-40%;width:120%;height:200%;background:linear-gradient(135deg,rgba(200,184,154,0.06),transparent 40%);transform:rotate(-12deg)}
    .lead{z-index:2}
    h1{margin:0 0 8px;font-size:22px;color:#fff}
    p.lead{margin:0;color:var(--muted)}
    .next-event{background:var(--glass);border-radius:10px;padding:18px;color:#eaf2f8;z-index:3}
    .meta{font-size:13px;color:var(--muted)}
    .btn{display:inline-block;background:var(--accent);color:#07202a;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:700}

    /* calendar list */
    .calendar{margin-top:22px;display:grid;gap:8px}
    .cal-item{padding:12px;border-radius:10px;background:rgba(255,255,255,0.02);display:flex;justify-content:space-between;align-items:center}
    .cal-item .info{font-size:14px}
    .cal-item .when{font-size:13px;color:var(--muted)}

    /* seat selector + packing list */
    .selector{display:flex;flex-direction:column;gap:10px}
    .controls{display:flex;gap:8px;align-items:center}
    .qty{width:44px;height:44px;border-radius:8px;border:1px solid rgba(255,255,255,0.06);display:grid;place-items:center;font-weight:700}
    .icon-btn{background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted);padding:8px;border-radius:8px}
    .packing{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
    textarea{width:100%;height:110px;background:#031017;border:1px solid rgba(255,255,255,0.02);color:#dfeaf2;padding:10px;border-radius:8px}
    footer{margin-top:30px;color:var(--muted);font-size:13px}

    .disclaimer{margin-top:12px;padding:10px;border-left:3px solid #c45d5d;background:rgba(196,93,93,0.03);color:#ffdede;border-radius:6px}

    @media(max-width:880px){.hero{grid-template-columns:1fr;}.brand{gap:8px}.wrap{padding:18px}}
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div class='brand'>
        <div class='logo'>SB</div>
        <div>
          <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
          <div style='font-size:13px;color:var(--muted)'>{ {TAGLINE} }</div>
        </div>
      </div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='events.html' class='active'>Gatherings</a>
        <a href='private-sessions.html'>Privates</a>
        <a href='pricing.html'>Rates</a>
        <a href='about.html'>About the Room</a>
        <a href='book.html'>Reserve</a>
      </nav>
    </header>

    <main>
      <section class='hero'>
        <div class='lead'>
          <h1>Gatherings in tuned layers — small, attentive groups</h1>
          <p class='lead'>Drop into an arranged soundscape designed to relieve tension and reorient the senses. Choose the next gathering below, hold a seat, and get a tailored packing list to arrive ready.</p>

          <div class='calendar' id='calendarList'>
            <!-- JS will populate -->
          </div>

          <div class='disclaimer'>
            <strong>Health &amp; safety:</strong> Some conditions can make sound immersion unsuitable. If you are pregnant, have a history of seizures, recent head injury, pacemaker or severe cardiac condition, please contact us before booking. This is not medical advice.
          </div>
        </div>

        <aside class='next-event'>
          <div style='display:flex;justify-content:space-between;align-items:center'>
            <div>
              <div style='font-size:13px;color:var(--muted)'>Next gathering</div>
              <div style='font-weight:800;font-size:16px' id='nextTitle'>Loading…</div>
              <div class='meta' id='nextWhen'>—</div>
            </div>
            <div style='text-align:right'>
              <div class='meta'>Seats left</div>
              <div style='font-weight:800;font-size:20px' id='seatsLeft'>—</div>
            </div>
          </div>

          <div style='margin-top:12px' class='selector'>
            <div class='controls'>
              <button id='minus' class='icon-btn'>−</button>
              <div class='qty' id='qty'>1</div>
              <button id='plus' class='icon-btn'>+</button>
              <button class='btn' id='reserveBtn'>Reserve</button>
            </div>

            <div class='packing' id='packingBox'>
              <strong style='display:block;margin-bottom:8px'>What to bring</strong>
              <div id='packingList'>—</div>
              <div style='display:flex;gap:8px;margin-top:10px'>
                <button id='copyPacking' class='icon-btn'>Copy list</button>
                <a href='book.html' class='btn' style='margin-left:auto'>Reserve now</a>
              </div>
            </div>
          </div>
        </aside>
      </section>
    </main>

    <footer>
      <div>Questions? Call <a href='tel:{{PHONE}}' style='color:var(--accent)'>{{PHONE}}</a> or email <a href='mailto:{{EMAIL}}' style='color:var(--accent)'>{{EMAIL}}</a></div>
      <div style='margin-top:8px;color:var(--muted)'>Calendar shown in local time for {{CITY}}, {{STATE}} — check times when reserving.</div>
    </footer>
  </div>

  <script>
    // Sample events (local only)
    const events = [
      {id:1,title:'Evening Drift — Deep Foam',date:'2026-03-05T19:00:00',type:'long',capacity:22,booked:16},
      {id:2,title:'Lumen Shift — Midweek Reset',date:'2026-03-12T18:00:00',type:'standard',capacity:18,booked:3},
      {id:3,title:'Slow Unbind — Gentle Close',date:'2026-03-20T20:00:00',type:'gentle',capacity:20,booked:20}
    ];

    function formatWhen(iso){
      const d=new Date(iso);
      return d.toLocaleString();
    }

    const calendarEl=document.getElementById('calendarList');
    events.forEach(ev=>{
      const item=document.createElement('div');
      item.className='cal-item';
      const free = Math.max(0, ev.capacity - ev.booked);
      item.innerHTML = "<div class='info'><strong>"+ev.title+"</strong><div class='when'>"+formatWhen(ev.date)+"</div></div><div style='text-align:right'><div class='when'>"+free+" seats</div><button class='icon-btn' data-id='"+ev.id+"'>Select</button></div>";
      calendarEl.appendChild(item);
    });

    // default next event = first not sold out
    let next = events.find(e=>e.capacity>e.booked) || events[0];
    document.getElementById('nextTitle').textContent = next.title;
    document.getElementById('nextWhen').textContent = formatWhen(next.date);
    let seatsLeft = Math.max(0,next.capacity-next.booked);
    document.getElementById('seatsLeft').textContent = seatsLeft;

    // seat selector
    const qtyEl=document.getElementById('qty');
    let qty=1; const minus=document.getElementById('minus'); const plus=document.getElementById('plus');
    minus.addEventListener('click',()=>{ if(qty>1){qty--; qtyEl.textContent=qty; updatePacking();}});
    plus.addEventListener('click',()=>{ if(qty<seatsLeft){qty++; qtyEl.textContent=qty; updatePacking();} });

    document.getElementById('reserveBtn').addEventListener('click',()=>{
      alert('This demo does not process payments.\n\nYou chose '+qty+' seat(s) for "'+next.title+'" on '+formatWhen(next.date)+'.\n\nProceed to the Reserve page to complete booking.');
    });

    // packing list generator
    function updatePacking(){
      const listEl=document.getElementById('packingList');
      const wantsBlanket = next.type === 'gentle' || next.type === 'long';
      const lines = [];
      lines.push('Seats: '+qty);
      lines.push('Bring: a yoga mat or thick blanket');
      if(wantsBlanket) lines.push('Extra: a folded blanket or shawl for warmth');
      lines.push('Optional: eye mask, water bottle, any small pillow');
      lines.push('Arrive: 15 minutes early to ground in the room');
      listEl.innerHTML = '<ul style=\'margin:0;padding-left:18px;\'><li>'+lines.join('</li><li>')+'</li></ul>';
    }
    updatePacking();

    // copy packing
    document.getElementById('copyPacking').addEventListener('click',()=>{
      const nodes = document.querySelectorAll('#packingList li');
      const text = Array.from(nodes).map(n=>n.textContent).join('\n');
      navigator.clipboard && navigator.clipboard.writeText(text).then(()=>{
        alert('Packing list copied to clipboard');
      },()=>{ alert('Copy not available in this browser'); });
    });

    // select from calendar to change next
    calendarEl.addEventListener('click',e=>{
      const btn = e.target.closest('button');
      if(!btn) return;
      const id = Number(btn.dataset.id);
      const ev = events.find(x=>x.id===id);
      if(!ev) return;
      next = ev;
      seatsLeft = Math.max(0,next.capacity-next.booked);
      document.getElementById('nextTitle').textContent = next.title;
      document.getElementById('nextWhen').textContent = formatWhen(next.date);
      document.getElementById('seatsLeft').textContent = seatsLeft;
      qty = 1; qtyEl.textContent = qty; updatePacking();
      window.scrollTo({top:0,behavior:'smooth'});
    });

  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Privates — {{BUSINESS_NAME}}</title>
  <meta name='description' content='Private and tailored sound sessions. Session planner to build your personalized session.'>
  <style>
    :root{--bg:#071018;--muted:#9fb0bf;--accent:#bfa678}
    *{box-sizing:border-box;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto}
    body{margin:0;background:linear-gradient(180deg,#071018,#08131a);color:#eaf2f8}
    .wrap{max-width:960px;margin:26px auto;padding:22px}
    header{display:flex;justify-content:space-between;align-items:center}
    .logo{width:56px;height:56px;border-radius:10px;background:linear-gradient(135deg,#bfa678,#7a5d3f);display:grid;place-items:center;font-weight:800}
    nav a{color:var(--muted);margin-left:12px;text-decoration:none}
    h1{margin:18px 0 8px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .card{background:rgba(255,255,255,0.02);padding:18px;border-radius:12px}

    /* session planner */
    .planner .row{display:flex;gap:10px;align-items:center;margin-bottom:10px}
    label{width:130px;color:var(--muted)}
    select,input[type='text']{flex:1;padding:8px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:#041319;color:#eaf2f8}
    .intentions{display:flex;gap:6px;flex-wrap:wrap}
    .chip{padding:8px 10px;border-radius:999px;background:rgba(255,255,255,0.02);cursor:pointer}
    .chip.active{background:linear-gradient(90deg,var(--accent),#a78b5e);color:#07202a}
    .summary{white-space:pre-wrap;background:#031419;padding:12px;border-radius:8px;border:1px solid rgba(255,255,255,0.02);height:160px;overflow:auto}
    .actions{display:flex;gap:8px;margin-top:8px}
    .btn{background:var(--accent);padding:10px 12px;border-radius:8px;color:#07202a;text-decoration:none;font-weight:700}
    .muted{color:var(--muted);font-size:13px}

    .disclaimer{margin-top:12px;padding:10px;border-left:3px solid #c45d5d;background:rgba(196,93,93,0.03);color:#ffdede;border-radius:6px}

    @media(max-width:900px){.grid{grid-template-columns:1fr}} 
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div style='display:flex;gap:12px;align-items:center'>
        <div class='logo'>PS</div>
        <div>
          <div style='font-weight:800'>Private Sessions</div>
          <div style='color:var(--muted);font-size:13px'>Book a focused, one-on-one sound session</div>
        </div>
      </div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='events.html'>Gatherings</a>
        <a href='private-sessions.html' style='color:var(--muted);margin-left:12px'>Privates</a>
        <a href='pricing.html' style='margin-left:12px'>Rates</a>
      </nav>
    </header>

    <main style='margin-top:16px'>
      <h1>Design your private sound session</h1>
      <p class='muted'>Use the planner to shape a session that matches your rhythm. Export a plain-text summary to paste into an email or your calendar.</p>

      <div class='grid'>
        <section class='card planner'>
          <div class='row'>
            <label>Session length</label>
            <select id='length'>
              <option value='30'>30 minutes</option>
              <option value='60' selected>60 minutes</option>
              <option value='90'>90 minutes</option>
            </select>
          </div>

          <div class='row'>
            <label>Setting</label>
            <select id='setting'>
              <option value='in_person' selected>In-person (studio)</option>
              <option value='home'>On-site (home visit)</option>
              <option value='remote'>Remote — guided from afar</option>
            </select>
          </div>

          <div class='row' style='align-items:flex-start'>
            <label>Primary focus</label>
            <div style='flex:1'>
              <div class='intentions' id='intentions'>
                <div class='chip' data-key='sleep'>Better sleep</div>
                <div class='chip' data-key='stress'>Release stress</div>
                <div class='chip' data-key='clarity'>Mental clarity</div>
                <div class='chip' data-key='body'>Body tension</div>
                <div class='chip' data-key='creative'>Creative opening</div>
              </div>
            </div>
          </div>

          <div class='row'>
            <label>Ambiance</label>
            <select id='ambiance'>
              <option value='minimal'>Minimal — dry room</option>
              <option value='reverb' selected>Rich — soft reverb</option>
              <option value='guided'>Narration led</option>
            </select>
          </div>

          <div class='row'>
            <label>Add-ons</label>
            <div style='flex:1'>
              <label style='display:flex;gap:8px;align-items:center'><input type='checkbox' id='addonPillow'> Cushion + support</label>
              <label style='display:flex;gap:8px;align-items:center'><input type='checkbox' id='addonCrystals'> Warm stones / crystals</label>
            </div>
          </div>

          <div style='margin-top:10px'>
            <div style='font-size:13px;color:var(--muted)'>Brief note for the practitioner (optional)</div>
            <input type='text' id='note' placeholder='Anything we should know?' />
          </div>

          <div class='actions'>
            <button class='btn' id='buildPlan'>Build my plan</button>
            <button id='copyPlan' class='icon' style='padding:10px;border-radius:8px;background:transparent;border:1px solid rgba(255,255,255,0.03);color:var(--muted)'>Copy text</button>
            <a href='book.html' class='btn' style='background:#8f7a5a;margin-left:auto'>Request session</a>
          </div>

        </section>

        <aside class='card'>
          <h3 style='margin-top:0'>Your session outline</h3>
          <div id='summary' class='summary'>No plan yet — press "Build my plan" to create a tailored outline.</div>

          <div class='disclaimer' style='margin-top:12px'>
            <strong>Contraindications:</strong> Private sessions involve vibrations and low-frequency sound. If you are pregnant, have a pacemaker, recent head trauma, or diagnosed epilepsy, please consult your clinician and contact us before booking.
          </div>

          <div style='margin-top:12px;color:var(--muted);font-size:13px'>Need a custom duration or group private? Email <a href='mailto:{{EMAIL}}' style='color:var(--accent)'>{{EMAIL}}</a> or call <a href='tel:{{PHONE}}' style='color:var(--accent)'>{{PHONE}}</a>.</div>
        </aside>
      </div>
    </main>
  </div>

  <script>
    // session planner logic
    const chips = document.querySelectorAll('.chip');
    const selected = new Set();
    chips.forEach(c=>{
      c.addEventListener('click',()=>{
        const k = c.dataset.key;
        if(selected.has(k)){ selected.delete(k); c.classList.remove('active'); }
        else { selected.add(k); c.classList.add('active'); }
      });
    });

    function buildOutline(){
      const length = document.getElementById('length').value;
      const setting = document.getElementById('setting').value;
      const ambiance = document.getElementById('ambiance').value;
      const note = document.getElementById('note').value || '—';
      const addons = [];
      if(document.getElementById('addonPillow').checked) addons.push('Support cushion');
      if(document.getElementById('addonCrystals').checked) addons.push('Warm stones / crystals');
      const intents = Array.from(selected);

      let text = '';
      text += 'Private sound session — '+length+' minutes\n';
      text += 'Setting: '+(setting==='in_person'?'Studio in person': setting==='home'?'On-site home visit':'Remote guidance')+'\n';
      text += 'Ambiance: '+(ambiance==='minimal'?'Minimal':'Rich reverb / warm pads')+'\n';
      text += 'Primary focus: '+(intents.length?intents.map(s=>s.charAt(0).toUpperCase()+s.slice(1)).join(', '):'General calm')+'\n';
      text += 'Add-ons: '+(addons.length?addons.join(', '):'None')+'\n';
      text += 'Note: '+note+'\n\n';
      text += 'Outline:\n';
      text += '- Arrival and settling (5–10 min)\n';
      text += '- Gentle tuning and breathable cues (5–10 min)\n';
      text += '- Layered sound immersion (remaining time)\n';
      text += '- Soft re-entry and time for questions\n\n';
      text += 'Contact: '+{{EMAIL}}+' or '+{{PHONE}}+' to confirm scheduling.';

      return text;
    }

    const summaryEl = document.getElementById('summary');
    document.getElementById('buildPlan').addEventListener('click',()=>{
      const t = buildOutline();
      summaryEl.textContent = t;
    });

    document.getElementById('copyPlan').addEventListener('click',()=>{
      const t = summaryEl.textContent;
      if(!t || t.includes('No plan')){ alert('Build a plan first.'); return; }
      navigator.clipboard && navigator.clipboard.writeText(t).then(()=>{ alert('Plan copied.'); },()=>{ alert('Copy not available.'); });
    });
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Rates & Add-ons — {{BUSINESS_NAME}}</title>
  <meta name='description' content='Pricing for group gatherings, private sessions, and optional retail add-ons.'>
  <style>
    :root{--bg:#06131a;--card:#071a20;--accent:#bfa678;--muted:#9fb0bf}
    body{margin:0;background:linear-gradient(180deg,#06131a,#07131a);color:#e8f2f7;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto}
    .wrap{max-width:980px;margin:28px auto;padding:22px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);margin-left:12px;text-decoration:none}
    h1{margin:12px 0}
    .cards{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:rgba(255,255,255,0.02);padding:16px;border-radius:12px}
    .price{font-weight:800;font-size:20px;color:var(--accent)}
    .addons{display:grid;gap:8px;margin-top:12px}
    .addon{display:flex;justify-content:space-between;align-items:center;padding:10px;border-radius:8px;background:rgba(255,255,255,0.01)}
    .calc{background:#03171a;padding:12px;border-radius:10px}
    .summary{white-space:pre-wrap;background:#021018;padding:10px;border-radius:8px;margin-top:10px;border:1px solid rgba(255,255,255,0.02)}
    .btn{background:var(--accent);padding:10px 12px;border-radius:8px;color:#07202a;text-decoration:none;font-weight:700}
    @media(max-width:920px){.cards{grid-template-columns:1fr}} 
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div>
        <div style='font-weight:800'>Pricing</div>
        <div style='color:var(--muted);font-size:13px'>Transparent rates and optional retail items</div>
      </div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='events.html'>Gatherings</a>
        <a href='private-sessions.html'>Privates</a>
      </nav>
    </header>

    <main style='margin-top:18px'>
      <h1>Packages & Add-ons</h1>
      <div class='cards'>
        <section class='card'>
          <h3 style='margin-top:0'>Group Gatherings</h3>
          <div style='display:flex;gap:12px;align-items:center'>
            <div>
              <div class='price'>$35</div>
              <div style='color:var(--muted);font-size:13px'>per person — typical 75–90 minute session</div>
            </div>
            <div style='margin-left:auto'>
              <a href='events.html' class='btn'>See calendar</a>
            </div>
          </div>

          <hr style='border:none;border-top:1px solid rgba(255,255,255,0.03);margin:12px 0'>

          <h3 style='margin-bottom:6px'>Private Sessions</h3>
          <div style='display:flex;gap:10px;align-items:center'>
            <div>
              <div style='font-weight:800'>$120</div>
              <div style='color:var(--muted);font-size:13px'>60-minute private (studio)</div>
            </div>
            <div style='margin-left:auto'><a href='private-sessions.html' class='btn' style='background:#8f7a5a'>Plan yours</a></div>
          </div>

          <div style='margin-top:12px;color:var(--muted);font-size:13px'>Bulk sessions and corporate rates available on request.</div>

          <div style='margin-top:14px'>
            <strong style='display:block;margin-bottom:8px'>Retail add-ons (purchase at booking)</strong>
            <div class='addons'>
              <label class='addon'><span>Hand-stitched blanket</span><span>$28 <input type='checkbox' data-price='28' class='addonCheck' style='margin-left:8px'></span></label>
              <label class='addon'><span>Travel eye pillow</span><span>$14 <input type='checkbox' data-price='14' class='addonCheck' style='margin-left:8px'></span></label>
              <label class='addon'><span>Organic botanical spray</span><span>$12 <input type='checkbox' data-price='12' class='addonCheck' style='margin-left:8px'></span></label>
            </div>
          </div>
        </section>

        <aside class='card'>
          <h3 style='margin-top:0'>Price builder</h3>
          <div class='calc'>
            <div style='margin-bottom:8px'>
              <label style='display:block;color:var(--muted);font-size:13px'>Choose a package</label>
              <select id='pkg' style='width:100%;padding:8px;border-radius:8px;background:#041819;border:1px solid rgba(255,255,255,0.02);color:#eaf2f8'>
                <option value='group' data-price='35'>Group — $35 per person</option>
                <option value='private' data-price='120'>Private (60m) — $120</option>
                <option value='private90' data-price='170'>Private (90m) — $170</option>
              </select>
            </div>

            <div style='margin-bottom:8px'>
              <label style='display:block;color:var(--muted);font-size:13px'>Quantity</label>
              <input id='qty' type='number' value='1' min='1' style='width:100%;padding:8px;border-radius:8px;background:#041819;border:1px solid rgba(255,255,255,0.02);color:#eaf2f8'>
            </div>

            <div style='font-size:13px;color:var(--muted)'>Select add-ons below (also available as retail on arrival)</div>
            <div style='display:flex;flex-direction:column;gap:8px;margin-top:8px'>
              <label style='display:flex;justify-content:space-between;align-items:center'><span style='font-size:14px'>Blanket</span><input type='checkbox' class='calcAddon' data-price='28'></label>
              <label style='display:flex;justify-content:space-between;align-items:center'><span style='font-size:14px'>Eye pillow</span><input type='checkbox' class='calcAddon' data-price='14'></label>
              <label style='display:flex;justify-content:space-between;align-items:center'><span style='font-size:14px'>Botanical spray</span><input type='checkbox' class='calcAddon' data-price='12'></label>
            </div>

            <div style='margin-top:12px;display:flex;gap:8px;align-items:center'>
              <div style='font-size:13px;color:var(--muted)'>Total</div>
              <div style='margin-left:auto;font-weight:800;font-size:18px;color:var(--accent)' id='total'>$0</div>
