      <div style='margin-top:18px;color:var(--muted);font-size:13px'>Note: prices shown are examples and subject to change. All sessions include a brief consultation and time to return to seated awareness. If you have medical questions, consult your clinician.</div>
    </main>
  </div>

  <script>
    function currency(n){ return '$'+(n.toFixed(2)); }
    function compute(){
      const pkg = document.getElementById('pkg');
      const price = Number(pkg.selectedOptions[0].dataset.price);
      const qty = Math.max(1,Number(document.getElementById('qty').value||1));
      const addChecks = document.querySelectorAll('.calcAddon');
      let addons = [];
      let addonTotal = 0;
      addChecks.forEach(a=>{ if(a.checked){ const p=Number(a.dataset.price); addons.push({label:a.previousSibling? a.previousSibling.textContent.trim():'Addon',price:p}); addonTotal+=p; } });
      const subtotal = (price*qty)+addonTotal;
      document.getElementById('total').textContent = currency(subtotal);
      const parts = [];
      parts.push('Selection summary');
      parts.push('Package: '+pkg.value+' ('+currency(price)+')');
      parts.push('Quantity: '+qty);
      if(addons.length) parts.push('Add-ons: '+addons.map(a=>a.label+' ('+currency(a.price)+')').join(', '));
      parts.push('\nTotal: '+currency(subtotal));
      parts.push('\nTo reserve, proceed to the Reserve page or contact '+ '{{EMAIL}}' +'.');
      document.getElementById('receipt').textContent = parts.join('\n');
    }

    document.getElementById('calcBtn').addEventListener('click',compute);
    document.getElementById('copyPrice').addEventListener('click',()=>{
      const t = document.getElementById('receipt').textContent;
      if(!t || t.includes('No selection')){ alert('Calculate first.'); return; }
      navigator.clipboard && navigator.clipboard.writeText(t).then(()=>{ alert('Price summary copied.'); },()=>{ alert('Copy not available.'); });
    });

    // init
    document.addEventListener('DOMContentLoaded',()=>{ compute(); });
  </script>
</body>
